function f(){const r="";async function o(t,n){const e=await fetch(`${r}${t}`,n);if(!e.ok){const a=await e.json().catch(()=>({detail:"Request failed"}));throw new Error(a.detail||`HTTP ${e.status}`)}return e.json()}function i(t){return o(t)}function s(t,n){return o(t,{method:"POST",headers:{"Content-Type":"application/json"},body:n?JSON.stringify(n):void 0})}function c(t,n){return o(t,{method:"PUT",headers:{"Content-Type":"application/json"},body:n?JSON.stringify(n):void 0})}function u(t){return o(t,{method:"DELETE"})}async function d(t){const n=new FormData;n.append("file",t);const e=await fetch(`${r}/api/upload`,{method:"POST",body:n});if(!e.ok){const a=await e.json().catch(()=>({detail:"Upload failed"}));throw new Error(a.detail||`HTTP ${e.status}`)}return e.json()}return{get:i,post:s,put:c,del:u,upload:d}}export{f as u};
